local InkwellMaker = {}
local PRODUCTS = {
    iron_inkwell = { name = "Železna črnilnica", ironCost = 2, woodCost = 2, leatherCost = 1, time = 4, cost = 135, prestige = 3, happiness = 2, description = "Železna črnilnica za pisarje." },
    bronze_inkwell = { name = "Bronasta črnilnica", bronzeCost = 2, ironCost = 1, woodCost = 2, leatherCost = 1, time = 6, cost = 330, prestige = 5, happiness = 3, description = "Bronasta črnilnica za pisarne." },
    silver_inkwell = { name = "Srebrna črnilnica", silverCost = 2, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 10, cost = 800, prestige = 10, happiness = 4, description = "Srebrna črnilnica za plemiške pisarje." },
    gilded_inkwell = { name = "Pozlačena črnilnica", goldCost = 1, silverCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 14, cost = 1720, prestige = 19, happiness = 5, description = "Pozlačena črnilnica za dvorne pisarje." },
    jewel_set_inkwell = { name = "Draguljasta črnilnica", goldCost = 2, silverCost = 2, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 18, cost = 3720, prestige = 35, happiness = 7, description = "Draguljasta črnilnica za kraljevske pisarje." },
    royal_sovereign_inkwell = { name = "Kraljevski suverena črnilnica", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 25, cost = 8000, prestige = 67, happiness = 13, description = "Suverena črnilnica z biseri za krono." },
}
local BUILDINGS = {
    inkwell_workshop = { name = "Črnilnična delavnica", cost = { gold = 295, wood = 175, stone = 120, iron = 6 }, upkeep = 5, qualityBonus = 5 },
    inkwell_house = { name = "Črnilnična hiša", cost = { gold = 1100, wood = 355, stone = 255, silver = 6, iron = 6 }, upkeep = 23, qualityBonus = 18 },
    master_inkwell_atelier = { name = "Mojstrski črnilnični atelje", cost = { gold = 2850, wood = 415, stone = 495, silver = 32, gold = 6 }, upkeep = 67, qualityBonus = 30 },
    sovereign_inkwell_palace = { name = "Suverena črnilnična palača", cost = { gold = 12400, wood = 640, stone = 800, gold = 79, jewel = 18 }, upkeep = 245, qualityBonus = 55, prestigeBonus = 50 },
}
InkwellMaker.ironStock = 12; InkwellMaker.bronzeStock = 10; InkwellMaker.woodStock = 14; InkwellMaker.leatherStock = 10; InkwellMaker.silverStock = 8; InkwellMaker.goldStock = 6; InkwellMaker.jewelStock = 4; InkwellMaker.pearlStock = 4
InkwellMaker.productStock = {}; InkwellMaker.buildings = {}; InkwellMaker.maker = nil; InkwellMaker.activeMaking = {}; InkwellMaker.totalProducts = 0; InkwellMaker.dayTimer = 0
function InkwellMaker.init() InkwellMaker.ironStock=12; InkwellMaker.bronzeStock=10; InkwellMaker.woodStock=14; InkwellMaker.leatherStock=10; InkwellMaker.silverStock=8; InkwellMaker.goldStock=6; InkwellMaker.jewelStock=4; InkwellMaker.pearlStock=4; InkwellMaker.productStock={}; InkwellMaker.buildings={}; InkwellMaker.maker=nil; InkwellMaker.activeMaking={}; InkwellMaker.totalProducts=0; InkwellMaker.dayTimer=0; print("[InkwellMaker] Royal Inkwell Maker System initialized (6 products, 4 buildings)") end
function InkwellMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; InkwellMaker.maker={name=n or ("Črnilničar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Črnilničar najet: %s (spretnost: %d)",InkwellMaker.maker.name,s),"success") end; return true end
function InkwellMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function InkwellMaker.build(id) local ok,e=InkwellMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(InkwellMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function InkwellMaker.getQualityBonus() local b=0; for _,bd in ipairs(InkwellMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function InkwellMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and InkwellMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and InkwellMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and InkwellMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and InkwellMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and InkwellMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and InkwellMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and InkwellMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and InkwellMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #InkwellMaker.buildings==0 then return false,"Potrebna črnilnična delavnica" end; if not InkwellMaker.maker then return false,"Potreben crnilnicar" end; return true end
function InkwellMaker.make(pt,qty) qty=qty or 1; local ok,e=InkwellMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then InkwellMaker.ironStock=InkwellMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then InkwellMaker.bronzeStock=InkwellMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then InkwellMaker.woodStock=InkwellMaker.woodStock-d.woodCost*qty end; if d.leatherCost then InkwellMaker.leatherStock=InkwellMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then InkwellMaker.silverStock=InkwellMaker.silverStock-d.silverCost*qty end; if d.goldCost then InkwellMaker.goldStock=InkwellMaker.goldStock-d.goldCost*qty end; if d.jewelCost then InkwellMaker.jewelStock=InkwellMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then InkwellMaker.pearlStock=InkwellMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if InkwellMaker.maker then t=math.max(1,t-math.floor(InkwellMaker.maker.skill/13)) end; table.insert(InkwellMaker.activeMaking,{id="inkwell_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function InkwellMaker.completeMaking(m) local q=1.0+(InkwellMaker.getQualityBonus()/100); if InkwellMaker.maker then q=q+(InkwellMaker.maker.skill/140) end; q=math.min(2.5,q); InkwellMaker.productStock[m.productType]=(InkwellMaker.productStock[m.productType] or 0)+m.quantity; InkwellMaker.totalProducts=InkwellMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if InkwellMaker.maker then InkwellMaker.maker.itemsMade=InkwellMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then InkwellMaker.maker.skill=math.min(100,InkwellMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Črnilnica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"inkwell.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function InkwellMaker.update(dt) if not _G.state then return end; InkwellMaker.dayTimer=InkwellMaker.dayTimer+dt; if InkwellMaker.dayTimer>=30 then InkwellMaker.dayTimer=0; for i=#InkwellMaker.activeMaking,1,-1 do local m=InkwellMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then InkwellMaker.completeMaking(m); table.remove(InkwellMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(InkwellMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if InkwellMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function InkwellMaker.getStats() return {ironStock=InkwellMaker.ironStock,bronzeStock=InkwellMaker.bronzeStock,woodStock=InkwellMaker.woodStock,leatherStock=InkwellMaker.leatherStock,silverStock=InkwellMaker.silverStock,goldStock=InkwellMaker.goldStock,jewelStock=InkwellMaker.jewelStock,pearlStock=InkwellMaker.pearlStock,productStock=InkwellMaker.productStock,numBuildings=#InkwellMaker.buildings,hasMaker=InkwellMaker.maker~=nil,makerName=InkwellMaker.maker and InkwellMaker.maker.name or "—",makerSkill=InkwellMaker.maker and InkwellMaker.maker.skill or 0,activeMaking=#InkwellMaker.activeMaking,totalProducts=InkwellMaker.totalProducts} end
return InkwellMaker
